def solve(inputs: dict) -> float:
    X = inputs['initial_value']
    num_steps = inputs['num_steps']

    # Mask to keep values in 32 bits
    MASK = (1 << 32) - 1

    for _ in range(num_steps):
        X ^= (X << 13) & MASK
        X ^= (X >> 9)
        X ^= (X << 17) & MASK
        X &= MASK

    return float(X)
